create or replace function public.calcular_data_fatal(p_data_base date, p_dias integer) returns date language sql immutable set search_path = '' as $funcao$ select case when p_data_base is null or p_dias is null or p_dias < 1 then null else ( select max(dia) from ( select (serie)::date as dia, row_number() over (order by serie) as posicao from generate_series((p_data_base + 1)::timestamp, (p_data_base + (p_dias * 2) + 10)::timestamp, interval '1 day') as serie where extract(isodow from serie) < 6 ) as uteis where posicao = p_dias ) end $funcao$